cycle = [1, 3, 5, 7, 9]

def fill_row(row):
    """Fill all holes in row using cycle pattern"""
    # Build a map of non-zero values by column
    non_zero = [(c, v) for c, v in enumerate(row) if v != 0]

    if not non_zero:
        return row

    # For each hole, find the nearest non-zero to the right as anchor
    for h_col in range(28):
        if row[h_col] == 0:
            # Find rightmost non-zero
            anchor_col = None
            for ac in range(h_col + 1, 28):
                if row[ac] != 0 and row[ac] in cycle:
                    anchor_col = ac
                    break

            if anchor_col is not None:
                anchor_val = row[anchor_col]
                anchor_idx = cycle.index(anchor_val)
                for fc in range(h_col, anchor_col):
                    if row[fc] == 0:
                        dist = anchor_col - fc
                        val_idx = (anchor_idx + dist) % 5
                        row[fc] = cycle[val_idx]

    return row

